create table if not exists public.otp_codes(id uuid primary key default gen_random_uuid(),phone_number text not null,code text not null,expires_at timestamptz not null,attempt_count integer not null default 0,ip_address text,created_at timestamptz not null default now());create index if not exists idx_otp_p on public.otp_codes(phone_number);create index if not exists idx_otp_e on public.otp_codes(expires_at);create or replace function public.fn_cleanup_expired_otps() returns void language sql security definer as $$ delete from public.otp_codes where expires_at<now()-interval '1 hour';$$;
